# -*- coding: utf-8 -*-
# 第 151-175 课内容数据
LESSONS_PART = [

# ============ 第10章 UI 界面系统 (151-170) ============
{"num":151,"title":"Slider 滑动条","summary":"掌握 Slider：音量、难度、进度条等数值调节 UI，读取与设置数值。","keywords":"slider,滑动条,音量条,数值调节,onvaluechanged","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握 Slider 创建","掌握读取数值","掌握数值变化事件"],
 "intro":"音量滑块、难度条、加载进度条都是 Slider。本课掌握滑动条。",
 "sections":[
  {"h":"Slider 组件","lead":"拖一个滑动条。",
   "steps":["Hierarchy 右键 → UI → Slider，创建滑动条。","结构：Slider（根）→ Background（背景条）→ Fill Area → Fill（填充）+ Handle Slide Area → Handle（滑块）。","【组件属性】","Min Value / Max Value：最小值/最大值。","Value：当前值。","Direction：方向（左到右/右到左/上到下…）。","Whole Numbers：只取整数。","【读取】slider.value 返回当前值。","【设置】slider.value = 50;","【事件 On Value Changed】值变化时调用方法（音量实时调整）。","【注意】Fill 填充条需要 Image Type 设为 Filled 或 Sliced（第 149 课）。"],
   "tips":[{"t":"note","c":"Slider 本体“长相”由子物体决定：Fill 是填充、Handle 是滑块。"}]},
  {"h":"实战：音量设置","lead":"拖动调节音量。",
   "steps":["在场景放一个 AudioSource（第 172 课），准备一首背景音乐。","创建脚本 AudioSettings：","public Slider volumeSlider;","public AudioSource bgm;","void Start() { volumeSlider.value = 1f; volumeSlider.onValueChanged.AddListener(SetVolume); }","void SetVolume(float v) { bgm.volume = v; Debug.Log(\"音量：\" + v); }","把 Slider 与 AudioSource 拖到对应槽。","播放：拖动滑块，背景音乐音量实时变化。","【自动朗读】把 Slider 的 Min 0 / Max 1 / Value 1，配合音量天然 0-1。","【其他用途】难度滑块（1-5）、敏感度滑块、加载进度条（配合协程更新 value）。","【禁用】slider.interactable = false 时不可拖。","【事件参数】onValueChanged 的回调会自动传入新值（float）。"],
   "tips":[{"t":"success","c":"音量调节 = Slider 值 → AudioSource.volume。两行代码打通。"}]},
 ],
 "errors":[{"err":"滑动条拖动没反应？","why":"Handle 的 Image 缺 Raycast Target，或 Slider 被遮挡","fix":"确认 Handle Slide Area 可点击；检查是否有 UI 遮挡。"}],
 "exercise":["做一个音量滑块实时调音量","做一个 0-100 的难度滑块","用 onValueChanged 打印数值变化"],
 "summary":"Slider 已掌握。下一课学 InputField 输入框。"},

{"num":152,"title":"InputField 输入框","summary":"掌握 InputField：玩家输入文字，读取与校验输入，回车提交。","keywords":"inputfield,输入框,文字输入,读取输入,tmp_inputfield","time":"约 13 分钟","difficulty":"入门",
 "objectives":["掌握 InputField 创建","掌握读取输入","掌握输入事件"],
 "intro":"玩家登录、改名、填答案都要输入框。本课实现文字输入交互。",
 "sections":[
  {"h":"InputField 组件","lead":"创建与配置。",
   "steps":["Hierarchy 右键 → UI → Input Field - TextMeshPro（推荐）。","结构：InputField（根）→ Text Area → Placeholder（提示文字）+ Text（实际文字）。","【Placeholder】提示“请输入…”的灰字；【Text】玩家输入后显示的黑字。","【组件属性】","Content Type：内容类型（Standard 普通、Integer Number 整数、Password 密码等）。","Character Limit：最大字符数（0=不限）。","Line Type：Single Line（单行）/ Multi Line（多行）。","【读取】tmpInput.text 返回当前输入内容（string）。","【设置】tmpInput.text = \"默认文字\";","【交互】interactable=false 禁用；readOnly 只读。","【注意】TMP 的输入框组件是 TMP_InputField，别与旧版 InputField 混用。"],
   "tips":[{"t":"note","c":"读取输入 = .text；转数字 = int.Parse/.TryParse（第 49 课）。"}]},
  {"h":"实战：登录输入","lead":"读取并处理输入。",
   "steps":["创建 InputField（用户名）+ InputField（密码，Content Type=Password）。","创建按钮“登录”。","创建脚本 LoginManager：","public TMP_InputField nameInput; public TMP_InputField pwdInput;","public void OnLogin() {","string name = nameInput.text;","string pwd = pwdInput.text;","if (string.IsNullOrEmpty(name)) { Debug.Log(\"请输入用户名\"); return; }","Debug.Log($\"登录：{name} / {pwd}\");","}","把按钮 On Click 绑定 OnLogin。","【数字输入】int.Parse(inputField.text) 前先 TryParse 判空判非法（第 49 课）。","【回车提交】用 TMP_InputField.onSubmit.AddListener(OnSubmit)；或 onEndEdit 失焦时触发。","【焦点】EventSystem 里 SetSelectedGameObject(inputField.gameObject) 让输入框自动聚焦。","【注意】输入时游戏按键可能被触发（第 112 课冲突），用 EventSystem.current.currentSelectedGameObject 判断焦点。","【验证】输入名字点登录，Console 打印。"],
   "tips":[{"t":"success","c":"登录/注册界面 = InputField ×2 + Button + 读取校验。标准三件套。"}]},
 ],
 "errors":[{"err":"输入框无法输入？","why":"EventSystem 缺失、或输入框被禁用、或焦点没在输入框","fix":"确认 EventSystem 存在；点击输入框后再输入；检查 interactable。"}],
 "exercise":["创建用户名+密码两个输入框","读取输入并打印","用 TryParse 安全转换数字输入"],
 "summary":"InputField 已掌握。下一课学 Toggle 开关。"},

{"num":153,"title":"Toggle 开关","summary":"掌握 Toggle：开关、多选、单选框组（Toggle Group），做设置选项。","keywords":"toggle,开关,单选框,toggle group,多选,isOn","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握 Toggle 创建","掌握 isOn 读取","掌握单选框组"],
 "intro":"“是否开声音”“选择角色职业”——Toggle 开关与单选框搞定。",
 "sections":[
  {"h":"Toggle 基础","lead":"勾选框。",
   "steps":["Hierarchy 右键 → UI → Toggle，创建开关。","结构：Toggle（根）→ Background → Checkmark（对勾）+ Label（文字）。","【组件属性】","Is On：当前是否勾选。","【读取】toggle.isOn 返回 bool。","【设置】toggle.isOn = true;","【事件 On Value Changed】勾选变化时回调（bool 参数）。","【改文字】Label 的 TMP 文字改成“开启音效”。","【改外观】Checkmark 的 Image 是那个对勾；Background 是方框。","【注意】Toggle 的“选中样式”由 Checkmark 是否显示决定（勾选时显示）。"],
   "tips":[{"t":"note","c":"读取开关 = toggle.isOn。设置界面大量用到。"}]},
  {"h":"Toggle Group 单选框","lead":"多个开关只能选一个。",
   "steps":["【需求】“性别/职业/难度”单选：选了 A 自动取消 B。","【创建 Toggle Group】Hierarchy 右键 → UI → Toggle Group（空对象带 Toggle Group 组件）。","【设置】把组对象拖到每个 Toggle 的【Group】槽，并把 Toggle 设为 Group 的子物体。","【组属性】Allow Switch Off：是否允许全部取消（通常不勾）。","【效果】组内 Toggle 互斥：点一个自动取消其他。","【读取选中】遍历组内 Toggle 找 isOn==true 的那个：","foreach (var t in GetComponentsInChildren<Toggle>()) { if (t.isOn) { Debug.Log(\"选中：\" + t); } }","【或】用 ToggleGroup.ActiveToggles()（进阶）。","【实战】难度选择：简单/普通/困难三个 Toggle 一组，读取选中的难度。","【注意】不设 Group 则多个 Toggle 互不影响。"],
   "tips":[{"t":"success","c":"单选 = Toggle Group；多选 = 独立 Toggle。设置界面直接抄。"}]},
 ],
 "errors":[{"err":"Toggle 组里能同时勾多个？","why":"没设 Group 或 Group 没挂对","fix":"把所有 Toggle 的 Group 槽指向同一个 Toggle Group 对象。"}],
 "exercise":["做一个“开启音效”开关并读取 isOn","做三个难度单选框（Toggle Group）","读取当前选中的难度"],
 "summary":"Toggle 已掌握。下一课学 Dropdown 下拉框。"},

{"num":154,"title":"Dropdown 下拉框","summary":"掌握 Dropdown：选项列表、读取选中、动态增删选项。","keywords":"dropdown,下拉框,选项,选项列表,onvaluechanged","time":"约 12 分钟","difficulty":"入门",
 "objectives":["掌握 Dropdown 创建","掌握选项管理","掌握选中事件"],
 "intro":"“选择角色”“选择语言”用下拉框最省空间。本课掌握 Dropdown。",
 "sections":[
  {"h":"Dropdown 组件","lead":"创建与配置选项。",
   "steps":["Hierarchy 右键 → UI → Dropdown - TextMeshPro，创建下拉框。","【组件属性】","Options：选项列表（每项有文本，可加图片）。","Value：当前选中的索引（从 0 开始）。","【读取】dropdown.value 返回选中索引；dropdown.options[value].text 返回选中文字。","【设置】dropdown.value = 2;","【事件 On Value Changed】选中变化时回调（int 索引参数）。","【结构】Dropdown → Template（下拉面板）+ Label + Arrow（箭头）。","【注意】TMP 的下拉框是 TMP_Dropdown，别与旧版混用。"],
   "tips":[{"t":"note","c":"读取下拉 = .value 索引 + .options[value].text 文字。"}]},
  {"h":"动态选项与实战","lead":"代码加选项。",
   "steps":["【静态配置】在 Inspector 的 Options 列表里直接添加选项（点 + 加项、输入文字）。","【代码动态】","TMP_Dropdown dd = GetComponent<TMP_Dropdown>();","dd.ClearOptions(); // 清空","dd.AddOptions(new List<string> { \"战士\", \"法师\", \"弓箭手\" });","【读取选中】","int idx = dd.value;","string cls = dd.options[idx].text;","Debug.Log($\"选择职业：{cls}\");","【事件】dd.onValueChanged.AddListener(OnClassChange); void OnClassChange(int i) { ... }","【实战】角色创建界面：职业下拉 + 确定按钮。","【默认值】dd.value 在 Inspector 设默认选中项。","【注意】ClearOptions 后要重新 AddOptions；选项为 0 时交互异常。"],
   "tips":[{"t":"success","c":"下拉框动态选项 = ClearOptions + AddOptions(List<string>)，一行搞定。"}]},
 ],
 "errors":[{"err":"下拉框打开没选项？","why":"Options 为空","fix":"在 Inspector 添加选项或用代码 AddOptions。"}],
 "exercise":["创建下拉框并配置 3 个静态选项","读取选中项的文本","用代码动态添加职业选项"],
 "summary":"Dropdown 已掌握。下一课学 ScrollView 滚动视图。"},

{"num":155,"title":"ScrollView 滚动视图","summary":"掌握 ScrollView：可滚动列表、滚动条、内容区，做物品栏/排行榜。","keywords":"scrollview,滚动视图,滚动列表,scrollrect,滚动条,content","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解 ScrollView 结构","掌握内容滚动","实现可滚动列表"],
 "intro":"背包几十件物品一屏放不下——ScrollView 让它“能滑”。本课掌握滚动列表。",
 "sections":[
  {"h":"ScrollView 结构","lead":"认识“卷轴”。",
   "steps":["Hierarchy 右键 → UI → Scroll View，创建滚动视图。","结构：Scroll View（根）→ Viewport（可视窗口）→ Content（内容区，可滚动范围）+ Scrollbar Horizontal/Vertical（滚动条）。","【ScrollRect 组件】核心：控制滚动。","Viewport 引用、Content 引用、滚动方向（Horizontal/Vertical）、惯性等。","【原理】Content 比 Viewport 大，滚动 = 移动 Content 在 Viewport 内显示位置。","【Content 大小】决定能滚多远（高度/宽度）。","【注意】Content 需要有 Layout 或手动设置大小，否则滚不动。"],
   "tips":[{"t":"note","c":"结构记忆：Viewport 是“窗户”，Content 是“纸”，滚动=纸在窗户后移动。"}]},
  {"h":"实战：物品列表","lead":"做出可滚动的物品栏。",
   "steps":["创建 ScrollView，确认 Content 是 Viewport 的子物体。","【Content 配置】给 Content 添加 Vertical Layout Group（第 156 课）让它自动排列子项。","【布局参数】Padding（内边距）、Spacing（间距）、Child Alignment（对齐）。","【Content Size Fitter】加 Content Size Fitter，Vertical Fit 选 Preferred Size：让 Content 高度随内容自动撑开。","【添加物品项】在 Content 下创建几个子物体（每项一个 Image+文字，可做成预制体）。","【滚动】播放后拖动/滚轮滑动，列表上下滚动。","【代码填充】用第 150 课的批量实例化把物品预制体填进 Content（设置父物体为 Content）。","【Mask 裁剪】Viewport 自带的 Mask/Image 保证超出窗口的部分被裁剪。","【注意】Content 没有 Content Size Fitter 时，手动设置高度决定滚动范围。","【优化】几千条列表用“虚拟列表”（进阶），普通游戏直接填即可。"],
   "tips":[{"t":"success","c":"滚动列表 = ScrollView + Layout Group 自动排列 + Content Size Fitter 撑高度，三件套。"}]},
 ],
 "errors":[{"err":"列表滚不动？","why":"Content 大小没撑开，或 ScrollRect 引用缺失","fix":"Content 加 Content Size Fitter + 子项用 Layout 撑开；检查 ScrollRect 的 Content 引用。"}],
 "exercise":["创建 ScrollView 并放 10 个物品项","用 Vertical Layout Group 自动排列","用代码把物品预制体批量填进列表"],
 "summary":"ScrollView 已掌握。下一课学布局组件。"},

{"num":156,"title":"布局组件 Layout Group","summary":"掌握布局组件：自动排列 UI、动态增删不散乱，四类布局器的选择。","keywords":"layout group,布局,自动排列,vertical layout,horizontal,grid layout","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解布局组件作用","掌握三种布局器","掌握 Content Size Fitter"],
 "intro":"“一堆按钮自动排整齐”“格子自动对齐”——布局组件自动排列子物体，加项不用手动摆。",
 "sections":[
  {"h":"布局器类型","lead":"按排列方式选。",
   "steps":["【Vertical Layout Group 垂直】子物体竖直排列（纵向列表、菜单）。","【Horizontal Layout Group 水平】子物体横向排列（一排按钮、导航栏）。","【Grid Layout Group 网格】子物体按网格排（物品栏、地图格子）。","【添加】给“容器对象”（如 Content、Panel）添加对应 Layout Group 组件。","【属性】","Padding：内边距（四方向）。","Spacing：子项间距。","Child Alignment：子项整体对齐（左上、居中…）。","Child Force Expand / Control Size：是否强制子项撑满/控制大小。","【效果】子物体自动排列、间距一致、增删自动重排。","【注意】Layout Group 会覆盖子物体的位置（手动拖的位置无效）。"],
   "tips":[{"t":"note","c":"布局组件 = “自动排版工”：告诉它怎么排，它替你摆整齐。"}]},
  {"h":"Content Size Fitter","lead":"让容器“跟着内容变大”。",
   "steps":["【问题】Content 里子项多了，容器高度不自动变大，滚动失效。","【解决】给 Content 加【Content Size Fitter】组件。","【属性】Horizontal Fit / Vertical Fit：","Unconstrained：不限制；Preferred Size：按子项期望大小撑开。","通常 Vertical Fit 设 Preferred Size 让高度随内容增长。","【组合】Layout Group（排子项）+ Content Size Fitter（撑容器）= 动态列表核心。","【布局刷新】内容动态增删后，布局可能需要重建：LayoutRebuilder.ForceRebuildLayoutImmediate(rectTransform)（进阶）。","【元素本身】子项也可以有自己的布局（嵌套布局）。","【实战】把第 155 课的物品列表加上 Grid Layout Group（3 列网格），自动排列物品。","【注意】Layout 与手动 RectTransform 定位冲突时，以布局为准。"],
   "tips":[{"t":"success","c":"动态 UI 铁三角：Layout Group 排子项 + Content Size Fitter 撑容器 + ScrollView 滚动。"}]},
 ],
 "errors":[{"err":"子物体位置乱/被布局打乱？","why":"Layout Group 覆盖了手动位置","fix":"子物体交给布局管理，别手动拖位置；想单独控制就用 Child Control Size 关掉。"}],
 "exercise":["用 Horizontal Layout 排 5 个按钮","用 Grid Layout 做 3 列物品格","给容器加 Content Size Fitter 观察自适应"],
 "summary":"布局组件已掌握。下一课学锚点与 RectTransform。"},

{"num":157,"title":"锚点 Anchor 与 Rect Transform","summary":"理解 UI 定位：锚点、轴心、RectTransform，做出随屏幕变化的自适应 UI。","keywords":"锚点,anchor,recttransform,轴心,pivot,定位","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解锚点概念","掌握锚点设置","掌握 RectTransform 定位"],
 "intro":"UI 元素“贴屏幕哪个位置”由锚点决定：左上角、右上角、居中、拉伸全屏。本课把 UI 定位彻底讲懂。",
 "sections":[
  {"h":"锚点 Anchor","lead":"UI 的“挂钩”。",
   "steps":["【RectTransform】UI 元素都有 RectTransform（代替 Transform），包含 Position、Size、Anchor、Pivot。","【锚点 Anchor】决定 UI 相对父对象（通常是 Canvas）的“挂钩位置”。","选中 UI 元素，Inspector 的 RectTransform 左上角有一个【Anchor Preset】九宫格图标。","点击它弹出预设：左上、右上、左下、右下、居中、拉伸等。","【效果】锚点=左上时，UI 固定在屏幕左上角，屏幕变大它跟着左上走。","【拉伸】选择“拉伸”预设（四条线撑满），UI 随屏幕缩放填满。","【锚点中心】点 Preset 右下角小图标可同时设置 Pivot。","【实战】把“开始按钮”锚点设为“中下”，让它在屏幕底部居中。"],
   "tips":[{"t":"note","c":"锚点九宫格：四角=贴角，中心=居中，拉伸=随屏缩放。做自适应 UI 的钥匙。"}]},
  {"h":"RectTransform 与 Pivot","lead":"定位与缩放的基准点。",
   "steps":["【Pos X/Y】相对锚点的位置（如中下锚点+PosY=50 → 底部上方 50）。","【Width/Height】UI 的宽高。","【Pivot 轴心】旋转/缩放的基准点（0,0=左下，0.5,0.5=中心，1,1=右上）。","改 Pivot 影响位置显示与缩放行为（如血条从左边涨就设 Pivot.x=0）。","【常用】文本/血条 Pivot.x=0（从左开始）、按钮中心 0.5。","【对齐】锚点+位置组合实现“屏幕角落”“居中”等。","【工具】Inspector 的 Rect 工具（工具栏 T 键）可在场景里拖动调整 UI 大小。","【全屏】锚点拉伸预设 + 四角 0 → UI 铺满屏幕。","【注意】Canvas 的 RectTransform 决定“参考区域”，子 UI 锚点相对它。"],
   "tips":[{"t":"success","c":"血条从左边扣 → Pivot.x=0 + 锚点底部；居中按钮 → 锚点中心 + Pivot 中心。"}]},
 ],
 "errors":[{"err":"UI 在某种分辨率下飞出屏幕？","why":"锚点/位置没配合好","fix":"把锚点设为“拉伸”或按四角对齐；用 Canvas Scaler（第 146 课）自适应。"}],
 "exercise":["把按钮锚点设为屏幕四角各看一次","做一个锚点拉伸的全屏背景","调整血条 Pivot 实现从左伸缩"],
 "summary":"锚点与 RectTransform 已掌握。下一课系统讲 UI 自适应屏幕。"},

{"num":158,"title":"UI 自适应屏幕","summary":"综合运用锚点与 Scaler，让 UI 在不同分辨率、不同屏幕下都美观不散。","keywords":"ui自适应,分辨率,屏幕适配,锚点,canvas scaler,safe area","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握自适应策略","掌握安全区适配","验证多分辨率"],
 "intro":"同一套 UI 要适应手机/平板/PC 不同屏幕，靠“锚点 + Scaler + 安全区”三件套。本课整合。",
 "sections":[
  {"h":"自适应策略","lead":"不同元素不同策略。",
   "steps":["【策略总览】","① 固定角落的元素（标题、按钮）：用锚点对齐四角/中心。","② 全屏背景/面板：用锚点拉伸（四边 0）。","③ 需要随屏幕变化的元素：锚点拉伸 + Scaler 缩放。","【Canvas Scaler】Scale With Screen Size + 参考分辨率 1920x1080 + Match 0.5（第 146 课）。","【背景图】背景 Image 锚点四角拉伸，任何分辨率都铺满。","【标题】锚点中上 + PosY 固定。","【按钮组】锚点中下 + 布局组件。","【实战】做一个“标题（上）+ 主按钮（中）+ 底部信息（下）”的界面，切分辨率验证不乱。","【验证】Game 视图把 Aspect 切换为 16:9、4:3、9:16 分别查看。","【注意】极端比例（超宽屏）需额外适配（Layout 与锚点结合）。"],
   "tips":[{"t":"note","c":"自适应心法：背景拉伸、元素贴边、Scaler 兜底。三种手段配合。"}]},
  {"h":"安全区 Safe Area","lead":"适配刘海屏。",
   "steps":["【问题】全面屏手机顶部有刘海/挖孔，UI 被遮挡。","【Safe Area】指屏幕“安全区域”（避开刘海、圆角、底部手势条）。","【方案1 组件】给 Canvas 加 SafeArea 脚本（网上常见）或自写：","RectTransform rt = GetComponent<RectTransform>();","Rect safe = Screen.safeArea;","Vector2 min = safe.position;","Vector2 max = safe.position + safe.size;","rt.anchorMin = new Vector2(min.x / Screen.width, min.y / Screen.height);","rt.anchorMax = new Vector2(max.x / Screen.width, max.y / Screen.height);","【方案2】把关键 UI 放进“安全区容器”（按 safeArea 拉伸的 Panel）。","【测试】编辑器右上角 Device Simulator 可模拟 iPhone 刘海屏（Window → General → Device Simulator）。","【注意】safeArea 只有移动端有意义，PC 上等于全屏。","【实战】把主界面容器适配 safeArea 并模拟刘海屏验证。"],
   "tips":[{"t":"success","c":"发布移动端前，用 Device Simulator 模拟刘海屏检查 UI 是否被遮挡。"}]},
 ],
 "errors":[{"err":"真机上 UI 被刘海挡住？","why":"没做安全区适配","fix":"给根容器应用 safeArea 方案；用 Device Simulator 提前模拟。"}],
 "exercise":["做一个多元素界面并验证多种分辨率","给主容器加 SafeArea 适配","用 Device Simulator 模拟刘海屏"],
 "summary":"UI 自适应已掌握。下一课学 UI 动画。"},

{"num":159,"title":"UI 动画（淡入淡出/移动）","summary":"给 UI 做动画：淡入淡出、滑入滑出、缩放弹跳，让界面有“生命”。","keywords":"ui动画,淡入淡出,fade,滑入,动画过渡,canvas group","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握 CanvasGroup","实现淡入淡出","实现滑入滑出"],
 "intro":"“菜单淡入、提示滑出”让游戏界面有质感。本课给 UI 加动画。",
 "sections":[
  {"h":"CanvasGroup 与淡入淡出","lead":"控制整组 UI 的透明度。",
   "steps":["【CanvasGroup】组件挂在 UI 容器上，统一控制其下所有子 UI 的透明度/交互。","【属性】Alpha（0-1 透明度）、Interactable（可交互）、Blocks Raycasts（阻挡点击）。","【淡入淡出原理】改 Alpha 值：0=全透明（看不见），1=不透明。","【代码淡入】","CanvasGroup cg;","IEnumerator FadeIn() {","cg.alpha = 0f;","while (cg.alpha < 1f) { cg.alpha += Time.deltaTime * 2f; yield return null; }","}","【淡出】同理把 alpha 减到 0，结束后 SetActive(false)。","【用途】菜单开关、提示气泡、死亡画面淡入。","【注意】Alpha=0 时仍占位置、可被点击，配合 Interactable/BlocksRaycasts=false 或 SetActive。","【动画方式】也可用 Animator 给 CanvasGroup.alpha 做动画（第 127 课）。"],
   "tips":[{"t":"success","c":"淡入淡出 = CanvasGroup.alpha 平滑变化。UI 动画第一步。"}]},
  {"h":"滑入滑出与缩放","lead":"移动与弹跳。",
   "steps":["【滑入】让面板从屏幕外滑进来：","RectTransform rt;","Vector2 offScreen = new Vector2(rt.anchoredPosition.x, -600f); // 屏幕下方","rt.anchoredPosition = offScreen;","while (rt.anchoredPosition.y < 0f) {","rt.anchoredPosition = Vector2.MoveTowards(rt.anchoredPosition, Vector2.zero, 800f * Time.deltaTime);","yield return null;","}","【滑出】反向移动后 SetActive(false)。","【缩放弹跳】从 0 放大到 1.1 再回 1：","rt.localScale = Vector3.zero;","while (rt.localScale.x < 1f) { rt.localScale += Vector3.one * Time.deltaTime * 3f; yield return null; }","【专业做法】用 Animator 状态机做这些过渡（可复用、可预览），或 DoTween 插件（第三方，超好用）。","【DoTween 简介】安装后一行：panel.DOFade(1f, 0.5f); 极其简洁，强烈推荐进阶。","【实战】做一个“设置面板”：点按钮滑入、关闭滑出。","【注意】UI 动画注意在关闭时禁用组件避免持续占用。","【体验】动画时长 0.2-0.4 秒手感最佳，太长拖沓。"],
   "tips":[{"t":"success","c":"UI 动画 = CanvasGroup 透明度 + anchoredPosition 移动 + localScale 缩放，三种自由度。"}]},
 ],
 "errors":[{"err":"淡出后还能点按钮？","why":"Alpha=0 但 BlocksRaycasts=true","fix":"淡出完成时把 BlocksRaycasts 设 false 或 SetActive(false)。"}],
 "exercise":["实现面板淡入淡出","实现设置面板滑入滑出","（进阶）安装 DoTween 用一行代码做动画"],
 "summary":"UI 动画已掌握。下一课做生命值血条。"},

{"num":160,"title":"生命值血条实现","summary":"用 Slider/Image.Filled 实现敌人/玩家血条，含头顶血条与 UI 血条。","keywords":"血条,生命值,health bar,fill,头顶血条,world space","time":"约 15 分钟","difficulty":"入门",
 "objectives":["实现 UI 血条","实现头顶血条","血条平滑与颜色变化"],
 "intro":"血条是游戏 UI 的“门面”。本课实现两种：屏幕角落 UI 血条 + 敌人头顶血条。",
 "sections":[
  {"h":"屏幕角落血条","lead":"玩家血条。",
   "steps":["创建 UI：Image 作为血条背景（黑/灰），再加一个子 Image 作为填充（红色或绿色）。","【填充】填充 Image 的 Image Type 选 Filled、Fill Method Horizontal。","【Pivot】填充条的 Pivot.x 设为 0（从左往右扣，第 157 课）。","【锚点】血条锚点设为“左上”，随屏幕固定。","【代码】在玩家脚本里：","public Image hpFill; // 拖入填充条","public int maxHp = 100; public int hp = 100;","void UpdateFill() { hpFill.fillAmount = (float)hp / maxHp; }","【说明】fillAmount 0-1：1=满血、0=空血。","【颜色】血量低时变红：hpFill.color = hp > 50 ? Color.green : Color.red;","【平滑】fillAmount 用 Lerp 平滑（白条延迟跟随）。","【测试】按空格扣血，血条变化。"],
   "tips":[{"t":"note","c":"fillAmount = hp/maxHp，一行驱动血条。"}]},
  {"h":"敌人头顶血条","lead":"World Space 血条。",
   "steps":["【方案】创建 Canvas，Render Mode 设为【World Space】（第 146 课）。","【大小】把 Canvas 缩放调小（如 0.01），放在敌人头顶上方（如 (0, 2, 0)）。","【背景】Canvas 下建 Image 背景 + Image 填充（同上面的结构）。","【父子】把 Canvas 作为敌人的子物体：敌人移动血条跟着。","【朝向】脚本让血条始终面向相机（不然从背面看是反的）：","void LateUpdate() { transform.LookAt(transform.position + Camera.main.transform.forward); }","【代码】跟 UI 血条一样设 fillAmount。","【显隐】血条在满血时不显示：hpFill.transform.parent.gameObject.SetActive(hp < maxHp);","【注意】World Space Canvas 大小要调 Scale，不然字/条巨大。","【性能】头顶血条多时注意合批（用图集）。","【完成】敌人在头顶显示血条，掉血实时更新！"],
   "tips":[{"t":"success","c":"头顶血条 = World Space Canvas + 子物体 + 面向相机 + fillAmount。"}]},
 ],
 "errors":[{"err":"头顶血条巨大/位置不对？","why":"World Space Canvas 缩放没调","fix":"把 Canvas 的 RectTransform Scale 调小（如 0.01）并摆好高度。"}],
 "exercise":["做屏幕角落的玩家血条","做敌人头顶血条并面向相机","实现低血量变红与平滑过渡"],
 "summary":"血条已实现。下一课做开始菜单。"},

{"num":161,"title":"开始菜单制作","summary":"制作完整的开始菜单：标题、按钮、背景、入场动画、进入游戏。","keywords":"开始菜单,主菜单,标题界面,main menu,入场动画","time":"约 18 分钟","difficulty":"入门",
 "objectives":["搭建开始菜单结构","添加菜单动画","实现进入游戏"],
 "intro":"游戏的第一印象就是主菜单。本课做一个专业感十足的开始菜单。",
 "sections":[
  {"h":"搭建菜单结构","lead":"标题 + 按钮 + 背景。",
   "steps":["新建场景 MainMenu。","创建 Canvas（Overlay + Scale With Screen Size 1920x1080）。","【背景】Image 全屏（锚点拉伸），放一张游戏截图/渐变图作为背景。","【标题】TMP 文本“我的游戏”（大号、居中、霓虹/描边效果），锚点中上。","【副标题】TMP 小字“版本 1.0”。","【按钮组】创建空对象 MenuButtons，用 Vertical Layout Group 垂直排列 3 个按钮：开始游戏 / 设置 / 退出。","【按钮样式】圆角九宫格背景 + TMP 文字（第 149-150 课）。","【版本信息】右下角小字。","【命名规范】按第 45 课规范命名所有 UI。","【事件系统】确认 Canvas 下有 EventSystem。"],
   "tips":[{"t":"note","c":"开始菜单是“UI 全家桶”的第一次完整应用：背景、文字、按钮、布局全用上。"}]},
  {"h":"入场动画与交互","lead":"让菜单“活”起来。",
   "steps":["【标题动画】给标题 TMP 加 Animator：从上方滑入 + 放大 + 淡入（第 159 课技巧或动画窗口）。","【按钮动画】按钮 hover 放大（IPointerEnter 改 scale，第 147 课）。","【背景动画】背景图缓慢流动（UV 偏移或整体缓动移动）。","【按钮功能】创建 UIManager 脚本：","public void StartGame() { SceneManager.LoadScene(\"Level1\"); }","public void OpenSettings() { settingsPanel.SetActive(true); }","public void QuitGame() { Application.Quit(); }","把按钮 On Click 绑定对应方法。","【退出提示】QuitGame 在编辑器里不生效（无窗口退出），可先打印验证。","【场景切换】记得把场景加入 Build Settings（第 235 课）。","【测试】播放：点开始进入游戏场景、点设置打开面板、点退出。","【注意】切场景后 Canvas 是当前场景的，脚本引用要当前场景内存在。"],
   "tips":[{"t":"success","c":"开始菜单 = 结构（背景/标题/按钮）+ 动画（入场/悬停）+ 交互（切场景）。三件套。"}]},
 ],
 "errors":[{"err":"点开始没切换场景？","why":"场景未加入 Build Settings 或 SceneManager 报错","fix":"File → Build Settings 把游戏场景加入列表；确认场景名与代码一致。"}],
 "exercise":["完成开始菜单（背景/标题/三按钮）","加标题入场动画与按钮悬停效果","绑定开始/设置/退出三个功能"],
 "summary":"开始菜单完成。下一课做暂停菜单。"},

{"num":162,"title":"暂停菜单与游戏暂停","summary":"实现暂停：Time.timeScale 暂停、暂停菜单、恢复与退出。","keywords":"暂停,pause,timescale,暂停菜单,恢复,esc","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握时间暂停","实现暂停菜单","实现恢复逻辑"],
 "intro":"“按 Esc 暂停、弹出菜单、再按恢复”——游戏标配。本课实现暂停系统。",
 "sections":[
  {"h":"Time.timeScale 暂停","lead":"暂停“整个世界的时间”。",
   "steps":["【原理】Time.timeScale = 0 时，游戏时间停止：Update 仍调用但 Time.deltaTime=0，物理停止，动画暂停。","【暂停】Time.timeScale = 0f;","【恢复】Time.timeScale = 1f;","【注意】Time.unscaledDeltaTime 不受暂停影响（做“暂停时也能动的 UI 动画”用）。","【Awake/Start 不受影响】协程用 WaitForSeconds 会暂停（受 timescale 影响），用 WaitForSecondsRealtime 不受影响。","【鼠标】暂停时解锁光标（Cursor.lockState=None）让玩家能点菜单。","【恢复】点“继续”时：Time.timeScale=1 + 锁回光标。","【防冲突】恢复时确认之前是暂停状态，避免重复设。","【重要】暂停不等于停止 Update：Update 里的非时间逻辑仍执行，注意用 if(Time.timeScale>0) 或 isPaused 控制。"],
   "tips":[{"t":"note","c":"timeScale=0 = 世界停摆；UI 动画要用 unscaled 时间才“照常动”。"}]},
  {"h":"实现暂停菜单","lead":"完整流程。",
   "steps":["创建暂停面板：Canvas 下的 Panel（遮罩）+ 3 按钮（继续/设置/退出主菜单）。","默认把面板 SetActive(false)。","创建 PauseManager：","public GameObject pausePanel;","private bool isPaused = false;","void Update() {","if (Input.GetKeyDown(KeyCode.Escape)) { TogglePause(); }","}","public void TogglePause() {","isPaused = !isPaused;","Time.timeScale = isPaused ? 0f : 1f;","pausePanel.SetActive(isPaused);","Cursor.lockState = isPaused ? CursorLockMode.None : CursorLockMode.Locked;","}","public void Resume() { if (isPaused) TogglePause(); }","public void QuitToMenu() { Time.timeScale = 1f; SceneManager.LoadScene(\"MainMenu\"); }","【按钮绑定】继续→Resume；退出主菜单→QuitToMenu。","【注意】退出主菜单前恢复 timeScale=1，否则下个场景也是暂停的！","【半透明遮罩】Panel 用半透明黑，视觉上“暗下来”。","【测试】Esc 暂停/恢复、退出回主菜单。"],
   "tips":[{"t":"danger","c":"切场景或退出前一定记得 Time.timeScale = 1，否则新场景“卡死”是新手高频坑。"}]},
 ],
 "errors":[{"err":"暂停后 UI 按钮也不动了？","why":"按钮动画用了受 timescale 影响的动画","fix":"暂停菜单的动画用 unscaled 时间或不受 timescale 影响。"}],
 "exercise":["实现 Esc 暂停/恢复","做暂停菜单（继续/退出）","退出前正确恢复 timeScale"],
 "summary":"暂停系统已实现。下一课做游戏结束画面。"},

{"num":163,"title":"游戏结束画面（胜负界面）","summary":"实现游戏结束：胜利/失败判定、结束面板、重新开始与返回菜单。","keywords":"游戏结束,结束画面,game over,胜利,失败,重新开始","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现结束判定","实现结束面板","实现重开与返回"],
 "intro":"“你赢了/你输了”的画面是游戏的“收官”。本课实现完整的结束流程。",
 "sections":[
  {"h":"结束判定","lead":"何时触发结束。",
   "steps":["【胜利条件】例如：消灭所有敌人、到达终点、收集全部金币。","【失败条件】例如：玩家血量归零、掉落深渊。","【判定代码示例】","在 GameManager 里：","public void PlayerDead() { ShowEnd(false); } // 失败","public void PlayerWin() { ShowEnd(true); } // 胜利","【触发点】血量<=0 时调用 PlayerDead()（玩家脚本里）；敌人清空/到达终点时调用 PlayerWin()。","【血量触发】在玩家脚本 TakeDamage 里 if (hp <= 0) GameManager.Instance.PlayerDead();","【掉落触发】玩家 y < -10 时触发。","【注意】触发一次即可，加个 isGameOver 标记防重复触发。","【结束状态】结束时可暂停游戏（Time.timeScale=0 或禁用输入）。"],
   "tips":[{"t":"note","c":"结束判定 = “条件 + 防重复 + 通知管理器”。三小步。"}]},
  {"h":"结束面板","lead":"显示结果与按钮。",
   "steps":["创建结束面板（默认隐藏）：半透明遮罩 + 标题（胜利/失败）+ 两个按钮（重新开始/返回主菜单）。","【两种标题】胜利面板与失败面板：可做两个 Panel（WinPanel/LosePanel）分别显示，或一个面板改文字颜色。","【显示】","public GameObject winPanel; public GameObject losePanel;","void ShowEnd(bool win) {","winPanel.SetActive(win);","losePanel.SetActive(!win);","Time.timeScale = 0f; // 结束暂停","Cursor.lockState = CursorLockMode.None;","}","【重新开始】public void Restart() { Time.timeScale = 1f; SceneManager.LoadScene(SceneManager.GetActiveScene().name); }","【返回主菜单】Time.timeScale = 1f; SceneManager.LoadScene(\"MainMenu\");","【淡入】面板用 CanvasGroup 淡入（第 159 课）更精致。","【完成】死亡/胜利时弹出对应面板，可重开可返回。","【注意】重新加载场景会重置一切，注意存档需求（第 232 课）。"],
   "tips":[{"t":"success","c":"结束流程 = 判定触发 → 显示面板 → 暂停 → 重开/返回。"}]},
 ],
 "errors":[{"err":"重复弹出结束面板？","why":"没加 isGameOver 防重复标记","fix":"加 bool isGameOver，触发一次后置 true 并禁用后续触发。"}],
 "exercise":["实现玩家死亡触发失败面板","实现消灭全部敌人触发胜利面板","实现重新开始与返回主菜单"],
 "summary":"结束画面已实现。下一课做对话框系统。"},

{"num":164,"title":"对话框系统","summary":"实现 NPC 对话：逐行显示文字、打字机效果、按键推进、选项分支。","keywords":"对话框,对话系统,npc对话,打字机效果,选项分支","time":"约 18 分钟","difficulty":"入门",
 "objectives":["搭建对话框 UI","实现打字机效果","实现对话推进与选项"],
 "intro":"“你好，旅人！”——NPC 对话是 RPG 的灵魂。本课做一个可扩展的对话框系统。",
 "sections":[
  {"h":"搭建对话框 UI","lead":"底栏对话框 + 文本。",
   "steps":["创建 UI：底部 Panel（半透明黑框）作为对话框。","对话框里放：NPC 名字 TMP（小字，如“老村长”）+ 对话内容 TMP（大字）。","加“点击继续”提示（小图标/文字，闪烁动画）。","【结构】DialogueBox（根 Panel）→ NameText + ContentText + ContinueHint。","【锚点】对话框锚点底部居中，宽度约屏幕 80%。","默认 SetActive(false)，与 NPC 交互时打开。","【交互触发】走到 NPC 面前按 E（触发器 + 按键，第 96 课 + 112 课）。"],
   "tips":[{"t":"note","c":"对话框 UI = 名字 + 内容 + 继续提示 三行。"}]},
  {"h":"打字机效果与对话推进","lead":"文字逐个跳出 + 点击推进。",
   "steps":["创建 DialogueSystem 脚本：","public TMP_Text contentText;","public string[] lines; // 对话行","private int lineIndex = 0;","public void StartDialogue(string[] newLines) {","lines = newLines; lineIndex = 0;","gameObject.SetActive(true);","StartCoroutine(TypeLine());","}","IEnumerator TypeLine() {","contentText.text = \"\";","foreach (char c in lines[lineIndex]) { contentText.text += c; yield return new WaitForSeconds(0.05f); }","}","public void NextLine() {","if (contentText.text == lines[lineIndex]) {","lineIndex++;","if (lineIndex < lines.Length) { StartCoroutine(TypeLine()); } else { EndDialogue(); }","} else {","// 点太快：直接显示整行","contentText.text = lines[lineIndex];","}","}","【按键推进】Update 里检测 E/鼠标左键调用 NextLine()。","【要点】打字中点击=跳过；打完点击=下一行；全说完=关闭。","【结束】EndDialogue() 关闭面板并通知（可解锁玩家控制）。"],
   "tips":[{"t":"success","c":"打字机 = 协程逐字显示；跳过与推进逻辑是对话“手感”关键。"}]},
  {"h":"选项分支（进阶）","lead":"让玩家选。",
   "steps":["【需求】对话中出现“接受任务 / 拒绝”两个选项。","【结构】对话行后放选项按钮组（默认隐藏），用 Vertical Layout 两个按钮。","【数据】行文本里用标记（如 “[Choice]”）表示“此行为选项”。","【实现】在 TypeLine 完成后检测行是否含选项标记，是则显示选项按钮。","【按钮绑定】选项A → 执行任务接受逻辑；选项B → 执行拒绝逻辑（可切到另一组对话）。","【代码示例】","if (lines[lineIndex].StartsWith(\"[Choice]\")) { choicePanel.SetActive(true); return; }","【简化】新手可先做“线性对话”（无选项），选项作为进阶。","【数据驱动】把对话数据放进 ScriptableObject（第 85 课）可策划配置。","【完成】一个可复用的对话系统完工！","【注意】对话时暂停玩家控制（锁定移动）。"],
   "tips":[{"t":"success","c":"对话系统 = UI + 打字机 + 推进 + （可选）选项。做完它，你的游戏“会说话”了。"}]},
 ],
 "errors":[{"err":"打字机卡住/文字不全？","why":"协程被中断或 lines 为空","fix":"确认协程正确启动；lines 非空；对话期间别停掉对象。"}],
 "exercise":["完成对话框 UI 与打字机效果","实现点击推进与结束","（进阶）加入选项分支"],
 "summary":"对话框系统完成。下一课做背包与物品栏。"},

{"num":165,"title":"背包与物品栏 UI","summary":"用网格布局 + 数据驱动实现物品栏：显示物品、点击查看、增删物品。","keywords":"背包,物品栏,格子,grid layout,物品数据,inventory","time":"约 18 分钟","difficulty":"入门",
 "objectives":["搭建网格物品栏","用数据驱动显示物品","实现物品交互"],
 "intro":"背包几十个格子、不同物品不同图标——本课用“数据驱动”思路做出可扩展的物品栏。",
 "sections":[
  {"h":"搭建物品栏 UI","lead":"格子 + 图标。",
   "steps":["创建物品栏面板：Panel（半透明）+ 标题“背包”。","【网格容器】Panel 下建空对象 Grid，加 Grid Layout Group（第 156 课）：Cell Size（如 90x90）、Spacing、Padding。","【格子背景】创建 Image 作为“格子底”（深色、九宫格边框），做成预制体 SlotPrefab。","【图标】格子内再放一个 Image（物品图标，默认空）。","【数量】可选：格子右下角 TMP 数量文字。","【批量生成格子】用代码实例化 20 个 SlotPrefab 填进 Grid（第 150 课批量技巧）。","【完成】20 个整齐格子出现。","【命名】Slot、SlotIcon、SlotCount。","【物品格数据】每个格子关联“物品数据”（ItemData，第 85 课 ScriptableObject）。"],
   "tips":[{"t":"note","c":"背包 = 网格 + 格子预制体 + 物品数据。数据驱动才是核心。"}]},
  {"h":"数据驱动显示物品","lead":"让物品“进格子”。",
   "steps":["【数据结构】定义简单物品类（或复用第 85 课 ItemData）：","[System.Serializable] public class Item { public string name; public Sprite icon; public int count; }","【背包数据】public List<Item> inventory = new List<Item>();","【显示逻辑】遍历格子与物品，把物品图标填进格子：","for (int i = 0; i < slots.Count; i++) {","if (i < inventory.Count) {","slots[i].icon.sprite = inventory[i].icon;","slots[i].icon.gameObject.SetActive(true);","slots[i].count.text = \"x\" + inventory[i].count;","} else { slots[i].icon.gameObject.SetActive(false); }","}","【添加物品】inventory.Add(new Item{...}); RefreshUI();","【移除物品】inventory.RemoveAt(index); RefreshUI();","【实战】按 G 键随机加一件物品，背包实时刷新。","【点击查看】格子加 Button/接口：点击显示物品详情（名字/描述）在侧边信息栏。","【注意】刷新 UI 要在数据变化后调用，保持“数据→UI”单向流动。","【优化】物品多时用对象池/虚拟列表（进阶）。"],
   "tips":[{"t":"success","c":"数据驱动心法：改数据 → 调 RefreshUI() → UI 重绘。数据是源头，UI 只是“显示器”。"}]},
 ],
 "errors":[{"err":"格子不刷新？","why":"改了数据没调 RefreshUI","fix":"在增删物品后调用刷新方法；确认刷新逻辑正确遍历。"}],
 "exercise":["搭出 20 格背包","用数据驱动显示随机物品","点击格子查看物品详情"],
 "summary":"背包系统完成。下一课学 UI 拖拽。"},

{"num":166,"title":"UI 拖拽与排序","summary":"实现 UI 元素拖拽：拖动图标、放入格子、交换物品、拖动条。","keywords":"ui拖拽,drag,idraghandler,拖放,排序,交换","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握拖拽接口","实现拖放交换","实现拖动面板"],
 "intro":"“把物品拖进格子”“拖动画板位置”——UI 拖拽用事件系统接口实现。本课掌握。",
 "sections":[
  {"h":"拖拽基础接口","lead":"四个接口搞定拖放。",
   "steps":["实现以下接口（using UnityEngine.EventSystems;）：","【IBeginDragHandler】开始拖：OnBeginDrag(PointerEventData)","【IDragHandler】拖动中：OnDrag(PointerEventData)","【IEndDragHandler】结束拖：OnEndDrag(PointerEventData)","【IDropHandler】被放上：OnDrop(PointerEventData)（目标格子实现）","【坐标】eventData.position 鼠标位置；拖动物体跟随：","public class DragUI : MonoBehaviour, IBeginDragHandler, IDragHandler, IEndDragHandler {","private RectTransform rt;","private Canvas canvas;","void Start() { rt = GetComponent<RectTransform>(); canvas = GetComponentInParent<Canvas>(); }","public void OnDrag(PointerEventData e) {","Vector2 pos;","RectTransformUtility.ScreenPointToLocalPointInRectangle(","canvas.transform as RectTransform, e.position, canvas.worldCamera, out pos);","rt.anchoredPosition = pos;","}","}","【注意】Canvas 的 Render Mode 会影响坐标转换（Overlay 时 worldCamera 为 null）。","【拖拽中的图片】拖拽时设置 canvasGroup.blocksRaycasts=false 防止自己挡住目标。"],
   "tips":[{"t":"note","c":"UI 拖拽 = 实现接口 + 坐标转换 + 拖动/放下回调。"}]},
  {"h":"拖放交换物品","lead":"把物品拖到另一格。",
   "steps":["在物品格子脚本 Slot 上实现 IBeginDragHandler/IDragHandler/IEndDragHandler（拖起自己）+ IDropHandler（被放下）。","【拖起】OnBeginDrag 记录源格子索引，设置跟随（第 166 课基础）。","【放下】目标格子的 OnDrop 里读取拖拽中的“源索引”（用一个静态变量传递），交换两个格子的物品数据。","【静态传递】public static int dragFromIndex = -1; 拖起时设源索引，放下时读取。","【交换逻辑】","void OnDrop(PointerEventData e) {","if (DragUI.dragFromIndex >= 0 && DragUI.dragFromIndex != myIndex) {","(inventory[myIndex], inventory[DragUI.dragFromIndex]) = (inventory[DragUI.dragFromIndex], inventory[myIndex]);","inventorySystem.RefreshUI();","}","DragUI.dragFromIndex = -1;","}","【拖拽可视化】拖起时把图标放到一个“临时拖拽层”并跟随鼠标，放下时归位。","【完成】物品可拖拽交换位置。","【进阶】拖到“丢弃区”删除物品；拖到“装备格”穿戴。","【注意】坐标转换与层级（拖拽层在最上层）是细节重点。"],
   "tips":[{"t":"success","c":"拖放交换 = 拖起记录索引 + 放下交换数据 + 刷新 UI。数据与 UI 分离。"}]},
 ],
 "errors":[{"err":"拖拽时图标不跟随鼠标？","why":"坐标转换错误或 Canvas 模式问题","fix":"用 RectTransformUtility.ScreenPointToLocalPointInRectangle 转换；Overlay 模式 worldCamera 传 null。"}],
 "exercise":["实现 UI 元素拖拽跟随鼠标","实现两个格子间的拖放交换","（进阶）实现拖拽到丢弃区"],
 "summary":"UI 拖拽已掌握。下一课学 UI 与代码交互。"},

{"num":167,"title":"UI 与代码交互（显示数据）","summary":"让 UI 实时显示游戏数据：分数、血量、倒计时，用事件驱动刷新。","keywords":"ui交互,显示数据,分数,实时刷新,事件驱动","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现数据→UI 更新","掌握刷新时机","用事件解耦"],
 "intro":"“分数变了，UI 文字要跟着变”。本课讲“数据→UI”的更新机制与最佳实践。",
 "sections":[
  {"h":"直接更新 vs 事件更新","lead":"两种刷新方式。",
   "steps":["【方式1 每帧刷新（简单）】在 UIManager 的 Update 里：scoreText.text = score.ToString();","优点：简单，数据随时最新。缺点：每帧更新浪费性能（文字不常变时）。","【方式2 事件驱动（推荐）】数据变化时通知 UI 刷新：","分数系统：","public event System.Action<int> OnScoreChanged;","public int score;","public void AddScore(int n) { score += n; OnScoreChanged?.Invoke(score); }","UI 订阅：","scoreSystem.OnScoreChanged += UpdateScoreText;","void UpdateScoreText(int s) { scoreText.text = \"分数：\" + s; }","【优点】只在数据变化时更新，性能好、解耦。","【方式3 数据变化手动刷新】调用公共方法 RefreshAllUI()。","【选择】高频变化（分数/血量）用事件；低频/简单用每帧刷新也无妨。","【注意】UI 刷新要防“空引用”（UI 未初始化时）。"],
   "tips":[{"t":"success","c":"专业做法：数据源发事件，UI 订阅刷新。数据与显示分离。"}]},
  {"h":"实战：分数与倒计时","lead":"做两个实时 UI。",
   "steps":["【分数 UI】Canvas 左上角 TMP “分数：0”。","ScoreManager 脚本（单例，第 86 课）：","public int score; public event System.Action<int> OnScoreChanged;","public void AddScore(int n) { score += n; OnScoreChanged?.Invoke(score); }","UIManager 订阅并刷新 scoreText。","【倒计时 UI】屏幕上方 TMP 显示剩余时间：","public TMP_Text timeText;","public float timeLeft = 60f;","void Update() { timeLeft -= Time.deltaTime; if (timeLeft <= 0) { timeLeft = 0; /* 时间到 */ }","timeText.text = \"时间：\" + Mathf.CeilToInt(timeLeft);","}","【死亡/胜利时停表】timeLeft<=0 触发结束（第 163 课）。","【组合】把分数/血量/时间都接进 UIManager，统一管理所有 UI 文本。","【注意】倒计时用 Time.deltaTime 会随暂停停（需要的话用 unscaledDeltaTime）。","【验证】游戏里加分/扣血/倒计时，UI 全部实时变化。","【完成】你的游戏有“仪表盘”了！"],
   "tips":[{"t":"note","c":"UI 刷新心法：数据源头唯一 + 事件通知 + UI 只读显示。"}]},
 ],
 "errors":[{"err":"UI 文字不更新？","why":"没订阅事件、或刷新时机不对","fix":"确认订阅了事件；数据变化调用了 Invoke；UI 组件引用正确。"}],
 "exercise":["实现分数 UI 的事件刷新","实现倒计时 UI","把血量/分数统一管理刷新"],
 "summary":"UI 数据交互已掌握。下一课做小地图。"},

{"num":168,"title":"小地图制作（UI 层）","summary":"实现 2D 小地图：雷达圈、玩家箭头、敌人红点，用坐标映射。","keywords":"小地图,雷达,minimap,坐标映射,地图,箭头","time":"约 15 分钟","difficulty":"入门",
 "objectives":["理解小地图原理","实现玩家位置箭头","实现敌人标记"],
 "intro":"右上角的雷达小地图实时显示玩家与敌人位置。原理是“世界坐标→地图坐标”的映射。本课实现。",
 "sections":[
  {"h":"小地图原理","lead":"世界坐标“压”到小图。",
   "steps":["【思路】把世界 XZ 坐标映射到小地图的 UI 位置。","【映射公式】地图位置 = 地图中心 + (世界坐标 - 世界中心) × 缩放比例。","【缩放比例】小地图 UI 大小 / 实际地图大小。","【中心】小地图中心对应世界中心（或玩家）。","【方案1 简化】让地图固定中心在“玩家初始位置”，用玩家相对偏移。","【方案2 相机法】用第二台正交相机渲染俯视图（性能高但复杂）。","【本课用方案1 纯 UI 映射，最灵活。","【坐标系】世界 X → UI 右（X），世界 Z → UI 上（Y，注意 UI 的 Y 向下为正需取反）。"],
   "tips":[{"t":"note","c":"小地图 = 世界坐标 → UI 坐标 的线性映射。公式：uiPos = center + (worldPos - worldCenter) * scale。"}]},
  {"h":"实现小地图","lead":"玩家箭头 + 敌人红点。",
   "steps":["【小地图 UI】创建 Canvas 右下角圆形/方形 Image（半透明黑）作为雷达背景，锚点右上。","【玩家箭头】建 Image 小箭头（▲），作为小地图的子物体，锚点中心。","【映射脚本 Minimap】","public RectTransform mapRect; // 小地图 RectTransform","public Transform player;","public RectTransform playerArrow;","public float worldRadius = 50f; // 实际地图半径","void Update() {","Vector3 offset = player.position; // 相对世界中心（这里假设中心原点）","float uiRadius = mapRect.rect.width * 0.5f;","float scale = uiRadius / worldRadius;","playerArrow.anchoredPosition = new Vector2(offset.x * scale, offset.z * scale);","playerArrow.localRotation = Quaternion.Euler(0, 0, -player.eulerAngles.y); // 箭头旋转对应朝向","}","【敌人红点】创建 List<RectTransform> 敌人箭头，遍历设置位置（同理映射）。","【世界中心】若玩家从 (0,0) 出发，offset=player.position 即可。","【边界】用 Clamp 限制红点在雷达圈内。","【注意】UI Y 轴向下，世界 Z 映射到 UI Y 时取负或符号统一（按实际朝向调）。","【完成】玩家箭头跟随、敌人红点显示。","【进阶】小地图边框、缩放雷达、迷雾。"],
   "tips":[{"t":"success","c":"小地图公式三件套：偏移 × 缩放 = 位置；-旋转 = 朝向；Clamp = 边界。"}]},
 ],
 "errors":[{"err":"箭头方向反了？","why":"UI 坐标方向与世界不一致","fix":"Y 取反或调整旋转符号（localRotation 用 -eulerAngles.y）。"}],
 "exercise":["做小地图背景与玩家箭头","实现玩家位置与朝向映射","加入 3 个敌人红点"],
 "summary":"小地图已实现。下一课做屏幕提示与对话气泡。"},

{"num":169,"title":"屏幕提示与对话气泡","summary":"实现屏幕中心提示、交互提示（按 E）、头顶对话气泡，完善交互反馈。","keywords":"屏幕提示,对话气泡,交互提示,world space气泡,提示系统","time":"约 15 分钟","difficulty":"入门",
 "objectives":["实现屏幕提示","实现交互提示","实现头顶气泡"],
 "intro":"“按 E 开门”“获得道具！”“NPC 头顶冒泡说话”——这些“反馈”让游戏人性化。本课实现三类提示。",
 "sections":[
  {"h":"屏幕中心提示","lead":"“拾取道具！”的浮动文字。",
   "steps":["【UI】Canvas 中心 TMP 文字（默认隐藏或透明）。","【代码】做一个通用的提示系统（单例）：","public class HintManager : MonoBehaviour {","public static HintManager Instance;","public TMP_Text hintText;","public CanvasGroup hintGroup;","void Awake() { Instance = this; }","public void ShowHint(string msg, float duration = 1.5f) {","hintText.text = msg;","StopAllCoroutines();","StartCoroutine(FadeHint(duration));","}","IEnumerator FadeHint(float d) {","hintGroup.alpha = 1f;","yield return new WaitForSeconds(d);","while (hintGroup.alpha > 0f) { hintGroup.alpha -= Time.deltaTime * 2f; yield return null; }","}","}","【调用】捡到金币时：HintManager.Instance.ShowHint(\"获得金币 +1\");","【完成】中心弹出提示并淡出。","【进阶】队列多条提示、从下往上弹出列表。","【注意】用单例便于任何脚本调用。"],
   "tips":[{"t":"success","c":"中心提示 = 单例 + 淡入淡出。所有“获得/解锁”通知都走它。"}]},
  {"h":"交互提示与头顶气泡","lead":"“按 E”与“说话”。",
   "steps":["【交互提示】当玩家靠近可交互物时，屏幕显示“按 E 开门”：","在可交互物脚本里：","public GameObject interactHint; // 屏幕下方提示","void OnTriggerEnter(Collider o) { if (o.CompareTag(\"Player\")) interactHint.SetActive(true); }","void OnTriggerExit(Collider o) { if (o.CompareTag(\"Player\")) interactHint.SetActive(false); }","触发区用 Is Trigger 碰撞体（第 96 课）。","【头顶气泡】NPC 头顶的对话气泡（World Space Canvas）：","创建 World Space Canvas（第 160 课头顶血条方法）作为 NPC 子物体，放 TMP 文本（默认隐藏）。","【显示气泡】NPC 脚本：","public GameObject bubble; public TMP_Text bubbleText;","public void Say(string msg) { bubbleText.text = msg; bubble.SetActive(true); Invoke(nameof(HideBubble), 2.5f); }","void HideBubble() { bubble.SetActive(false); }","【测试】靠近 NPC 显示“按 E”，按 E 后头顶冒泡说话。","【优化】气泡朝向相机（LookAt，第 160 课）。","【完成】一套完整的交互反馈体系。"],
   "tips":[{"t":"success","c":"反馈三件套：中心提示（全局）、交互提示（靠近显示）、头顶气泡（NPC 说话）。"}]},
 ],
 "errors":[{"err":"交互提示一直不消失？","why":"OnTriggerExit 没触发","fix":"确认触发区与玩家都有碰撞体；玩家带刚体；提示在 Exit 里隐藏。"}],
 "exercise":["实现中心提示系统并调用","实现“按 E”交互提示","实现 NPC 头顶对话气泡"],
 "summary":"提示系统完成。下一课综合练习：完整游戏主界面。"},

{"num":170,"title":"综合练习：完整游戏主界面","summary":"综合 UI 全部知识，做一个包含开始菜单、HUD、暂停、设置的完整界面。","keywords":"综合练习,主界面,完整ui,开始菜单,hud,设置界面","time":"约 30 分钟","difficulty":"入门",
 "objectives":["综合运用 UI 章全部知识","搭建完整界面体系","体验“游戏外壳”开发"],
 "intro":"把 UI 章所有能力整合成一套“游戏外壳”：主菜单、HUD、暂停、设置、结束画面齐全。UI 章毕业项目！",
 "sections":[
  {"h":"整体架构","lead":"一个 Canvas 还是多个。",
   "steps":["【场景规划】主菜单场景 MainMenu + 游戏场景 Game。","【UI 模块】游戏场景里用多个 Canvas（或一个 Canvas 分面板）：","① HUD：分数/血量/时间（左上角等）。","② PausePanel：暂停菜单。","③ SettingsPanel：设置（音量滑块等）。","④ WinPanel / LosePanel：结束画面。","⑤ HintText：中心提示。","【组织】建一个空对象 UIManager 挂 UIManager 脚本统一管理所有面板引用。","【原则】各面板默认隐藏，按需 Show/Hide。","【命名】按规范：HUD_Score、PausePanel 等。"],
   "tips":[{"t":"note","c":"先规划好“有哪些界面、何时出现”，再逐个搭，比边做边想高效。"}]},
  {"h":"搭建各模块","lead":"逐个实现。",
   "steps":["【HUD】左上分数 TMP + 血条（第 160 课）+ 顶部倒计时。","【设置面板】音量 Slider + 灵敏度 Slider + 关闭按钮（第 151 课）。","【暂停】Esc 弹出（第 162 课）。","【结束】死亡/胜利面板（第 163 课）。","【提示】中心提示系统（第 169 课）。","【主菜单】标题 + 开始/设置/退出（第 161 课）。","【测试数据】脚本里模拟：加分、扣血、死亡，看 UI 联动。","【交互】所有按钮都绑定功能：开始游戏、继续、重开、返回。","【完成】一套能“装进任何游戏”的 UI 外壳完工！"],
   "tips":[{"t":"success","c":"这套 UI 外壳可复用到你未来所有项目——好好保存这个场景。"}]},
  {"h":"验证与收尾","lead":"全链路测试。",
   "steps":["播放测试完整流程：主菜单 → 开始游戏 → HUD 显示 → Esc 暂停 → 设置调音量 → 死亡弹出结束 → 重开。","切换多种分辨率验证 UI 不散（第 158 课）。","检查 Console 无报错无警告。","清理无用引用、规范命名。","保存场景与项目。","【复盘】这次练习用到：Canvas、锚点、布局、Slider、Button、Text、Image、CanvasGroup、事件系统、Time.timeScale……UI 章全覆盖。","【延伸】把血条换成头顶血条、加入背包按钮等。","UI 章毕业！"],
   "tips":[{"t":"note","c":"UI 系统是“游戏的脸”，做完这套你已具备任何游戏的界面能力。"}]},
 ],
 "errors":[{"err":"切场景后 UI 引用丢失？","why":"UI 引用是当前场景的","fix":"把 UIManager 及 UI 放在对应场景；跨场景数据用单例/PlayerPrefs（第 238 课）。"}],
 "exercise":["完成主菜单+HUD+暂停+设置+结束的完整界面","全流程联调测试","（进阶）把设置保存到 PlayerPrefs"],
 "summary":"完整主界面完成！UI 章毕业。下一章进入音频系统，给游戏“加上声音”。"},

# ============ 第11章 音频系统 (171-185) ============
{"num":171,"title":"音频系统总览与 AudioSource","summary":"认识音频系统架构：AudioSource 播放、AudioClip 数据、AudioListener 听者。","keywords":"音频系统,audiosource,audioclip,audiolistener,播放声音","time":"约 13 分钟","difficulty":"入门",
 "objectives":["理解音频系统架构","掌握 AudioSource","掌握 AudioClip"],
 "intro":"背景音乐、音效、环境声都由 AudioSource 播放。本课建立音频系统整体认知。",
 "sections":[
  {"h":"音频三大组件","lead":"播放器、素材、听者。",
   "steps":["【AudioSource 音频源】“播放器”：挂在物体上，负责播放声音。一个物体可有多个 AudioSource。","【AudioClip 音频剪辑】“声音素材”：音频文件导入后的资产（.wav/.mp3 等，第 40 课）。","【AudioListener 音频监听器】“耳朵”：接收所有声音。每个场景通常一个，挂在 Main Camera 上。","【关系】AudioSource 拿到 AudioClip 播放 → AudioListener 听到 → 输出到扬声器。","【多音源】场景中可有很多 AudioSource，Listener 只能有一个。","【默认】新场景 Main Camera 自带 AudioListener；物体加 AudioSource 即可出声。","【声音文件导入】第 40 课已讲，直接拖进 Project。","【距离衰减】AudioSource 有 3D 音效属性（第 175 课），Listener 决定“从哪听”。","【注意】AudioListener 重复会报错（一个场景只能有一个）。"],
   "tips":[{"t":"note","c":"记忆：Source=喇叭、Clip=光盘、Listener=耳朵。三者齐了才有声。"}]},
  {"h":"AudioSource 核心属性","lead":"掌握常用参数。",
   "steps":["【AudioClip】要播放的素材槽。","【Mute】静音；【Bypass Effects】跳过效果。","【Play On Awake】对象激活时自动播放。","【Loop】循环播放（背景音乐勾选）。","【Priority】优先级（0 最高，255 最低）。","【Volume】音量（0-1）。","【Pitch】音调（1 正常，0.5 慢/低，2 快/高）。","【Stereo Pan】立体声左右平衡（-1 左，1 右）。","【Spatial Blend】3D 空间感：0=2D（全局声）、1=3D（随距离衰减）。","【3D Sound Settings】距离衰减曲线等（第 175 课）。","【播放控制】脚本：source.Play()/Stop()/Pause()/UnPause()；source.isPlaying 判断是否在播。","【注意】Volume 与 Pitch 是代码调音最常用的两个属性。","【实战】给 Main Camera 加 AudioSource，拖入背景音乐，勾 Loop 与 Play On Awake，播放即响。"],
   "tips":[{"t":"success","c":"AudioSource 五兄弟：Clip、Loop、Volume、Pitch、SpatialBlend，掌握即能用。"}]},
 ],
 "errors":[{"err":"没有声音？","why":"没 AudioListener、没 AudioSource、或没 AudioClip","fix":"确认相机有 AudioListener（且唯一）；物体有 AudioSource 且有 Clip；音量>0。"}],
 "exercise":["认识三大音频组件","给物体加 AudioSource 播放一段音效","理解 Source/Clip/Listener 的关系"],
 "summary":"音频系统已建立认知。下一课播背景音乐。"},

{"num":172,"title":"播放背景音乐","summary":"实现背景音乐：循环播放、音量控制、切换音乐、跨场景延续。","keywords":"背景音乐,bgm,循环播放,音乐切换,跨场景音乐","time":"约 14 分钟","difficulty":"入门",
 "objectives":["实现循环 BGM","实现音乐切换","实现跨场景延续"],
 "intro":"游戏一开就有背景音乐、切换场景不停。本课做一个“打不死”的 BGM 系统。",
 "sections":[
  {"h":"基础循环播放","lead":"最简单的 BGM。",
   "steps":["创建空对象 BGM，加 AudioSource。","【设置】AudioClip 拖入背景音乐；勾选 Loop（循环）；勾选 Play On Awake（开局就播）。","【音量】Volume 设 0.6 左右。","【播放】运行即响，循环不断。","【代码控制】","AudioSource bgm;","void Start() { bgm = GetComponent<AudioSource>(); }","public void PlayMusic(AudioClip clip) { bgm.clip = clip; bgm.Play(); }","public void StopMusic() { bgm.Stop(); }","public void SetVolume(float v) { bgm.volume = v; }","【切换音乐】换关卡时调用 PlayMusic(新音乐)。","【淡入淡出】切换时音量渐出渐入（协程）。","【注意】Loop 必须勾选，否则音乐播完就停。"],
   "tips":[{"t":"note","c":"BGM 核心：Loop 循环 + Play On Awake + 代码可切换。"}]},
  {"h":"跨场景延续（DontDestroyOnLoad）","lead":"切场景音乐不断。",
   "steps":["【问题】切场景会销毁当前场景对象，BGM 停掉。","【解决】用 DontDestroyOnLoad 让 BGM 对象跨场景存活：","public class BGM : MonoBehaviour {","public static BGM Instance;","void Awake() {","if (Instance != null) { Destroy(gameObject); return; } // 防重复","Instance = this;","DontDestroyOnLoad(gameObject);","}","}","【说明】首个 BGM 保留并跨场景；重复进入时销毁新增的。","【完整单例音乐管理器】把 PlayMusic/SetVolume 等并入，全局可用（第 86 课单例）。","【切场景验证】从主菜单进游戏，音乐不断。","【注意】DontDestroyOnLoad 的对象会在场景切换时保留，注意别造成重复。","【进阶】按场景切换不同 BGM（在场景加载时触发切换）。"],
   "tips":[{"t":"success","c":"跨场景 BGM = 单例 + DontDestroyOnLoad。所有全局管理器都用这套。"}]},
 ],
 "errors":[{"err":"切场景后两个音乐同时响？","why":"BGM 对象被重复创建","fix":"用单例检查 Instance 已存在则 Destroy 新对象（Awake 里）。"}],
 "exercise":["实现循环 BGM 并控制音量","用单例实现跨场景延续","实现切换不同 BGM"],
 "summary":"背景音乐系统完成。下一课学播放音效。"},

{"num":173,"title":"播放音效与随机音调","summary":"实现一次性的音效播放：跳跃、射击、碰撞声，带随机音调避免单调。","keywords":"音效,sfx,playsound,随机音调,一次音效,audiosource","time":"约 14 分钟","difficulty":"入门",
 "objectives":["掌握音效播放","掌握随机音调","掌握多音效管理"],
 "intro":"“哒哒哒”射击声、跳跃声、金币声——音效是游戏“手感”的一半。本课掌握 SFX 播放。",
 "sections":[
  {"h":"音效播放方式","lead":"三种常用方式。",
   "steps":["【方式1 物体自带 AudioSource】跳跃：给 Player 加 AudioSource，跳时 source.Play()。","【方式2 一次性播放（推荐）】AudioSource.PlayClipAtPoint(clip, position); 在世界某处播一次，自动销毁临时音源。","【方式3 全局音效管理器】单例 AudioManager 提供 PlaySFX(clip) 方法。","【一次性播放示例】","public AudioClip jumpSound;","void Jump() { AudioSource.PlayClipAtPoint(jumpSound, transform.position); }","【注意】PlayClipAtPoint 每次新建临时 AudioSource，频繁调用有性能开销（可用对象池优化，进阶）。","【事件触发】在动画事件里播脚步（第 135 课）。","【音效素材】导入 .wav 短音效（第 40 课），Load Type 用 Decompress On Load。","【音量】PlayClipAtPoint 的第 3 参数可设音量：PlayClipAtPoint(clip, pos, 0.8f)。"],
   "tips":[{"t":"note","c":"短音效用 PlayClipAtPoint 最省事；要精细控制（音量/暂停）用自带 AudioSource。"}]},
  {"h":"随机音调","lead":"让重复音效不“呆”。",
   "steps":["【问题】同一声效连播十次，听感单调机械。","【解决】每次播放随机 Pitch（0.9-1.1）与音量（0.9-1.0），模拟真实变化。","【实现】","public AudioSource sfx;","public AudioClip[] hitSounds; // 多个可选音效","void PlayHit() {","if (hitSounds.Length > 0) sfx.clip = hitSounds[Random.Range(0, hitSounds.Length)];","sfx.pitch = Random.Range(0.9f, 1.1f);","sfx.volume = Random.Range(0.9f, 1f);","sfx.Play();","}","【Random.Range】随机：int 时含两端；float 时不含上限。","【多个素材】准备 3-4 个同类型音效随机播放，变化更丰富。","【应用】脚步（多脚步素材）、攻击、碰撞、拾取。","【注意】Pitch 改变会改变音高（可用作“越撞越尖”的反馈）。","【完成】音效不再单调。"],
   "tips":[{"t":"success","c":"随机三件套：随机选素材 + 随机 Pitch + 随机音量。音效“活”起来。"}]},
 ],
 "errors":[{"err":"音效播不出来？","why":"AudioClip 没赋值、音量 0、或 Listener 缺失","fix":"确认 clip 已拖入；音量>0；场景有 AudioListener。"}],
 "exercise":["给跳跃加音效","实现随机音调与随机素材","用 PlayClipAtPoint 播一次性音效"],
 "summary":"音效播放已掌握。下一课学 AudioListener。"},

{"num":174,"title":"AudioListener 监听器","summary":"掌握 AudioListener：唯一“耳朵”、位置对音量的影响、多场景注意。","keywords":"audiolistener,监听器,耳朵,音量衰减,唯一","time":"约 11 分钟","difficulty":"入门",
 "objectives":["理解 AudioListener 作用","掌握位置影响","避免重复监听器"],
 "intro":"所有声音最终都“传”到 AudioListener。它是场景里唯一的“耳朵”，本课讲清楚它的规矩。",
 "sections":[
  {"h":"AudioListener 基础","lead":"一只“耳朵”。",
   "steps":["【作用】AudioListener 代表“听者”，接收场景中所有 AudioSource 的声音。","【位置】Listener 的位置影响 3D 音效的听感（离得近大声、远小声）。","【默认】Main Camera 自带 AudioListener，所以相机=听者。","【唯一性】一个场景只能有一个激活的 AudioListener，多个会报警告并可能异常。","【移除】若场景有多个带 Listener 的对象（如切换了相机），保留一个其余删除/禁用。","【2D 音效】Spatial Blend=0 的 2D 音效不受 Listener 位置影响（全屏音量）。","【3D 音效】受 Listener 距离影响（第 175 课）。","【静音】Listener 本身没有音量属性，静音通过各 Source 或 AudioMixer。","【常见错误】场景里有多个 AudioListener 报 warning：AudioListener in scene ... are disabled/There are 2 audio listeners","【修复】确保只有一个启用的 Listener。"],
   "tips":[{"t":"danger","c":"“两个耳朵”是常见警告：切场景/多相机时确认只留一个 AudioListener。"}]},
  {"h":"实战注意事项","lead":"正确使用。",
   "steps":["【方案】把 AudioListener 放在“玩家的耳朵”位置：通常相机自带即可。","【多相机】若你用了多个相机，只保留一个带 Listener，或在代码里动态切换：","if (useMainCam) mainCam.GetComponent<AudioListener>().enabled = true;","else { mainCam.GetComponent<AudioListener>().enabled = false; otherCam.GetComponent<AudioListener>().enabled = true; }","【头顶听者】第一人称时 Listener 在相机 = 玩家耳朵，3D 音效方向正确。","【第三人称】Listener 在相机（离角色较远），3D 音效按“相机距离”衰减（可接受）。","【角色位置优化】若要按“角色耳朵”衰减，把 Listener 放到角色头部子物体（进阶）。","【测试】放一个 3D 音效的 AudioSource，播放后移动相机/Listener，听音量随距离变化。","【注意】移动 Listener 会改变所有 3D 音效听感，谨慎调整。","【验证】Console 无“多个 AudioListener”警告。"],
   "tips":[{"t":"success","c":"AudioListener 就一句：场景唯一、放在“听者”位置。其余交给 3D 音效。"}]},
 ],
 "errors":[{"err":"警告：There are 2 audio listeners？","why":"场景有多个启用的 Listener","fix":"禁用/删除多余的，只保留一个。"}],
 "exercise":["确认场景只有唯一 AudioListener","把 Listener 移到不同位置感受 3D 音效变化","学会多相机时的 Listener 切换"],
 "summary":"AudioListener 已掌握。下一课学 3D 空间音频。"},

{"num":175,"title":"3D 空间音频与衰减","summary":"掌握 3D 音效：距离衰减、空间混合、多普勒，让声音有“方位感”。","keywords":"3d音效,空间音频,距离衰减,doppler,spatial blend,衰减曲线","time":"约 14 分钟","difficulty":"入门",
 "objectives":["理解 3D 音效原理","掌握衰减设置","掌握多普勒效果"],
 "intro":"“敌人的脚步声从左边传来，越走越近越大声”——3D 空间音频营造沉浸感。本课掌握。",
 "sections":[
  {"h":"3D 音效原理","lead":"声音“有位置”。",
   "steps":["【2D vs 3D】2D 音效无视位置（全局音量）；3D 音效随距离/方位变化。","【Spatial Blend】AudioSource 属性：0=纯 2D、1=纯 3D、中间值=混合。","【设为 1】做音效（脚步声、枪声）时 Spatial Blend=1，成为 3D 音效。","【3D 效果】","音量随距离衰减（靠近大声、远离小声）。","左右耳音量差/延迟实现方位感（Stereo Pan）。","【Doppler 多普勒】相对速度导致音调变化（救护车驶过“呜”的感觉），默认 1，可调 0 关闭。","【Min Distance / Max Distance】衰减范围：min 内音量不变、min 到 max 衰减、max 外无声。","【Volume Rolloff 衰减曲线】Logarithmic（对数，真实）/ Linear（线性，均匀）。","【注意事项】3D 音效要听得出方位，Listener 位置很重要（第 174 课）。"],
   "tips":[{"t":"note","c":"3D 音效 = Spatial Blend 1 + Min/Max 距离 + 衰减曲线。三样配置。"}]},
  {"h":"实战：环境音与脚步","lead":"做出有空间感的声音。",
   "steps":["【火焰/瀑布 3D 音效】给火焰粒子对象加 AudioSource：clip 火焰声、Spatial Blend=1、Loop、Min Distance 1、Max Distance 20。","播放后走近/走远，听音量变化。","【脚步 3D 音效】角色脚步：在脚部/身体加 AudioSource（Spatial Blend=1），动画事件触发播放（第 135 课）。","【多普勒测试】让一个音源快速掠过（速度大的刚体音源），听音调变化，Doppler Level 调大更明显。","【衰减曲线】把 Volume Rolloff 改成 Linear 对比 Logarithmic 的听感差异。","【曲线自定义】点开 Volume Rolloff 的曲线可手动编辑（进阶）。","【多个 3D 音源】场景多音源时，注意合并同类音源控性能。","【完成】你的游戏有了“空间感”。","【注意】3D 音效的衰减在 AudioSource 的 3D Sound Settings 里。","【推荐】角色音效用 3D（Spatial 1），UI 音效/BGM 用 2D（Spatial 0）。"],
   "tips":[{"t":"success","c":"分声音的“性格”：BGM/UI 声 2D 全局，角色/环境声 3D 有空间感。"}]},
 ],
 "errors":[{"err":"3D 音效走远就突然没声？","why":"Max Distance 太小","fix":"调大 Max Distance；或用 Logarithmic 衰减让渐变更自然。"}],
 "exercise":["做一个 3D 火焰声效并走近听变化","用多普勒体验音调变化","对比 2D 与 3D 音效的区别"],
 "summary":"3D 空间音频已掌握。下一课学 AudioMixer 混音器。"},
]
